We consider minimizing a smooth and strongly convex objective function:
\begin{equation}\label{pro:1}
\min_{\xb\in \mR^d}\; f(\xb),
\end{equation}
where $f:\mR^d\rightarrow \mR$ is twice continuously differentiable with $\Hb(\xb) = \nabla^2 f(\xb) \in \mR^{d\times d}$ being its Hessian matrix. We suppose the Hessian $\Hb(\xb)$ satisfies
\begin{equation*}
\lambda_{\min}\cdot \Ib \preceq \Hb(\xb) \preceq\lambda_{\max}\cdot\Ib, \quad\;  \forall \xb\in\mR^d,
\end{equation*}
for some constants $0<\lambda_{\min}\leq\lambda_{\max}$, and we let $\kappa = \lambda_{\max}/\lambda_{\min}$ denote its~condition number. We also let $\xb^\star = \arg\min_{\xb\in \mR^d} f(\xb)$ be the unique global~solution.


\begin{equation}\label{equ:Newton}
\xb_{t+1} = \xb_t - \mu_t \Hb_t^{-1}\nabla f_t,
\end{equation}

where $\nabla f_t = \nabla f(\xb_t)$, $\Hb_t = \Hb(\xb_t)$, and $\mu_t$ is selected by passing a line search condition. Classical results indicate that Newton's method in \eqref{equ:Newton} \mbox{exploits}~a~global $Q$-linear convergence in the error of function value $f(\xb_t)-f(\tx)$; and a local $Q$-quadratic convergence in the iterate error $\|\xb_t-\tx\|$. More precisely, Newton's method has two phases, separated by a neighborhood 


A parallel line of research explores stochastic Newton methods, where a stochastic approximation $\hHb_t$ is used in place of $\Hb_t$ in \eqref{equ:Newton}. The stochasticity of $\hHb_t$ may come from evaluating the Hessian on a random subset of data points~(i.e., subsampling), or from projecting the Hessian onto a random subspace to~achieve~the dimension reduction (i.e., sketching). To unify different approaches, we consider in this paper a general Hessian approximation given by a \textit{stochastic oracle}. In particular, we express the approximation $\hHb(\xb)$ at any point $\xb$ by
\begin{equation}\label{equ:error}
\hHb(\xb) = \Hb(\xb) + \Eb(\xb),
\end{equation}

where $\Eb(\xb)\in \mS^{d\times d}$ is a symmetric random noise matrix following a certain distribution (conditional on $\xb$) with mean zero. At iterate $\xb_t$, we query the oracle to obtain an approximation $\hHb_t = \hHb(\xb_t)$, which (implicitly) comes from generating a realization of the random matrix $\Eb_t = \Eb(\xb_t)$, and then adding $\Eb_t$ to the true Hessian $\Hb_t$. We do not assume $\Eb_t$ and $\Hb_t$ are accessible to us.


We consider an online averaging scheme (we let $\tHb_{-1} = \0$):
\begin{equation}\label{equ:ave:Hessian}
\tHb_t  = \frac{w_{t-1}}{w_t} \tHb_{t-1} + \rbr{1 - \frac{w_{t-1}}{w_t}}\hHb_t, \quad t = 0,1,2,\ldots,\\
\end{equation}

where $\{w_t\}_{t=-1}^{\infty}$ is a prespecified increasing non-negative weight sequence~starting with $w_{-1} = 0$. By \emph{online} we mean that we only keep an average Hessian $\tHb_t$ in each iteration, and update it as \eqref{equ:ave:Hessian} when we obtain a new Hessian estimate. This scheme is in contrast to keeping all the past Hessian estimates. By the scheme \eqref{equ:ave:Hessian}, we note that, at iteration $t$, we re-scale the weights of $\{\hHb_i\}_{t=0}^{t-1}$ equally by a factor of $w_{t-1}/w_t$, instead of completely redefining all the weights. We note that such an online averaging scheme is memory and computation efficient: compared to stochastic Newton methods without averaging, we only require an extra $O(d^2)$ space to save $\tHb_t$ and $O(d^2)$ flops to update it, which is negligible in the setting of stochastic Newton methods where the Hessian vector product requires $O(d^2)$ flops and solving the exact Newton system requires $O(d^3)$ flops. In \eqref{equ:ave:Hessian}, we use the ratio factors $w_{t-1}/w_t$ instead of direct weights merely to simplify our later presentation. Furthermore, \eqref{equ:ave:Hessian} can be reformulated as a general weighted average as follows:\vskip-0.32cm
\begin{equation}\label{equ:z}
\tHb_t =\sum_{i=0}^tz_{i,t}\hHb_i,\qquad\text{with}\quad
  z_{i,t}\coloneqq(w_i-w_{i-1})/w_t.
\end{equation}

\noindent In particular, by setting $w_t=t+1$, we obtain $z_{i,t} = 1/(t+1)$ and further have $\tHb_t = \frac1{t+1}\sum_{i=0}^{t}\hHb_i$. Thus, we recover simple uniform averaging. If we let the sequence $w_t$ grow faster-than-linearly,~this results in a weighted average that is skewed towards the more recent Hessian estimates. 


\begin{algorithm}[!t]
\caption{Stochastic Newton Method with Hessian Averaging}
\label{alg:1}
\begin{algorithmic}[1]
\State \textbf{Input}: iterate $\xb_0$, weights $\{w_t\}_{t=-1}^{\infty}$, scalars $\beta\in(0, 1/2)$, $\rho\in(0, 1)$, and $\tHb_{-1} = \0$;
\For{ $t = 0,1,2,\ldots$}
\State Obtain a stochastic Hessian approximation $\hHb_t = \Hb_t + \Eb_t$;
\State Compute the Hessian average via \eqref{equ:ave:Hessian}: $\tHb_t  = \frac{w_{t-1}}{w_t} \tHb_{t-1} + \rbr{1 - \frac{w_{t-1}}{w_t}}\hHb_t$;
\State Compute the Newton direction $\pb_t$ by solving: $\tHb_t\pb_t = -\nabla f_t$;\vspace{1mm}
\State \textbf{if} $\tHb_t\pb_t = -\nabla f_t$ is not solvable \textbf{or} $\nabla f_t^\top\pb_t\geq 0$, \ \textbf{then} \ skip iteration with~$\xb_{t+1}=\xb_t$; 
\State Compute a stepsize $\mu_t = \rho^{j_t}$, where $j_t$ is the smallest nonnegative integer such that
\begin{equation*}
\text{Armijo condition}:\hskip 0.5cm f(\xb_t+\mu_t\pb_t) \leq f(\xb_t) + \mu_t\beta \nabla f_t^\top\pb_t
\end{equation*}
\State Update $\xb_{t+1} = \xb_t +\mu_t\pb_t$;
\EndFor
\end{algorithmic}
\end{algorithm}

\noindent We mention that the superlinear rate is measured with respect to the error $\|\xb_t-\ttxb\|_{\ttHb} \coloneqq \sqrt{(\xb_t-\ttxb)^\top\ttHb(\xb_t-\xb_0)}$ where~$\ttHb = \Hb(\ttxb)$. Before introducing the main results in Theorems \ref{thm:main-1} and \ref{thm:main-2}, we summarize them in Table \ref{tab:1}, showing the transition points for~two weight sequences. The transitions for general weights are provided~in Section~\ref{sec:4}. We use $\Upsilon$ to denote the \textit{noise level} of stochastic Hessian oracle (see Assumption \ref{ass:3} for a formal definition; typically $\Upsilon = O(\kappa)$). We also use $O(\cdot)$ to suppress the logarithmic factors and the dependence on other constants except $\Upsilon$ and $\kappa$. We emphasize that all results of the~paper require that the (weighted) average of the errors $\{\Eb_i\}_{i=0}^t$ is sufficiently concentrated; thus, they hold \textit{with high probability}.


\noindent{\bf Notation}: Throughout the paper, we use $\Ib$ to denote the identity matrix,~and~$\0$ to denote the zero vector or matrix. Their dimensions are clear from the~context. We use $\|\cdot\|$ to denote the $\ell_2$ norm for vectors and spectral norm for matrices.  For a positive semidefinite matrix $\Ab$, we let $\|\xb\|_{\Ab} = \sqrt{\xb^\top\Ab\xb}$. For two scalars $a, b$, $a\vee b = \max(a,b)$ and $a\wedge b = \min(a, b)$. For two matrices $\Ab, \Bb$, $\Ab \prec (\preceq)\Bb$ if $\Bb - \Ab$ is a positive (semi)definite matrix. Recall that we reserve the notation $\lambda_{\min}, \lambda_{\max}$ to denote the lower and upper bounds of the true~Hessian, and~$\kappa = \lambda_{\max}/\lambda_{\min}$ is the condition number. 


Given a sequence  of stochastic iterates $\{\xb_t\}_{t=0}^{\infty}$, we let $\mF_0\subseteq\mF_1\subseteq\mF_2\subseteq\ldots$ be a filtration where $\mF_t = \sigma(\xb_{0:t})$, $\forall t\geq 0$, is the $\sigma$-algebra~generated~by~the randomness from $\xb_0$ to $\xb_t$. With such a filtration, we denote the~conditional~expectation by~$\mE_t[\cdot] = \mE[\cdot \mid \mF_t]$ and the conditional probability by $\mP_t(\cdot) = \mP(\cdot \mid \mF_t)$. We suppose $\xb_0$ is deterministic, so that $\mF_0$ is a trivial $\sigma$-algebra. 


For a given weight sequence $\{w_t\}_{t=-1}^\infty$ with $w_{-1}=0$, the scheme \eqref{equ:ave:Hessian} leads~to \vskip-0.4cm
\begin{equation}\label{equ:simple}
\tHb_t\;\; \stackrel{\mathclap{\eqref{equ:z}}}{=}\; \sum_{i=0}^{t}z_{i,t}\hHb_i \ \stackrel{\mathclap{\eqref{equ:error}}}{=} \!\!\underbrace{\sum_{i=0}^{t}z_{i,t}\Hb_i}_{\text{Hessian averaging}}\!\!+\!\!\quad\barEb_t\qquad\quad\text{for} \quad \barEb_t\coloneqq\!\!\underbrace{\sum_{i=0}^{t}z_{i,t}\Eb_i }_{\text{noise averaging}}
\end{equation}

\noindent where $z_{i,t} = (w_i - w_{i-1})/w_t$. Note that $\sum_{i=0}^t z_{i,t}=1$ and $z_{i,t}\propto z_i\coloneqq w_i-w_{i-1}$, i.e., $z_{i,t}$ is proportional to an un-normalized weight $z_i$. We see from \eqref{equ:simple} that~$\tHb_t$ consists of the Hessian averaging and noise averaging with the same weights. In principle, the Hessian averaging $\sum_{i=0}^{t}z_{i,t}\Hb_i\rightarrow \ttHb$ as $\xb_t\rightarrow \tx$, while the noise averaging $\sum_{i=0}^{t}z_{i,t}\Eb_i\rightarrow \0$ due to the central limit~theorem. We will show that the Hessian averaging (eventually) converges faster than the noise averaging.


To study the concentration of noise averaging $\barEb_t$, we use the fact that~$\{\Eb_t\}_{t=0}^\infty$ is a martingale difference sequence, and rely on concentration inequalities for matrix martingales. These concentration inequalities require a sub-exponential tail condition on the noise.  We say that a random variable $X$ is $K$-sub-exponential if $\mE[|X|^p]\leq p!\cdot K^p/2$ for all $p=2,3,...\,$, which is consistent (up to constants) with all standard notions of sub-exponentiality \citep[see Section 2.7 in][]{Vershynin2018High}.


\begin{assumption}[Sub-exponential noise]\label{ass:3}
We assume that  $\Eb(\xb)$ is mean zero and $\|\Eb(\xb)\|$ is $\Upsilon_E$-sub-exponential for all $\xb$. Also, we define $\Upsilon\coloneqq\Upsilon_E/\lambda_{\min}$ to be the scale-invariant noise level. 
\end{assumption}

\begin{assumption}[Lipschitz Hessian]\label{ass:4}
We assume $\Hb(\xb)$ is $L$-Lipschitz continuous. That is $\|\Hb(\xb_1) - \Hb(\xb_2)\|\leq L\|\xb_1 - \xb_2\|$ for any $\xb_1, \xb_2\in \mR^d$.
\end{assumption}

