\begin{theorem}\label{thm:3}	
Consider Algorithm \ref{alg:1} with $w_t = t+1$, $\forall t\geq 0$. Under Assumptions \ref{ass:3}, \ref{ass:4}, we let $\delta \in(0, 1)$ satisfy $d/\delta\geq e$, and let $\epsilon, \nu\in(0, 1)$ satisfy
\begin{equation}\label{cond:epsnu}
\epsilon \vee \nu \leq \frac{1}{3}\frac{0.5-\beta}{1.5-\beta}\wedge \frac{1}{48}.
\end{equation}
Define the neighborhood $\N_{\nu}$ as in \eqref{Nnu}, and define $\T = \T_1 +\T_2$ with $\T_1$ given~by \eqref{T1} and $\T_2$ given by \eqref{T2}. We also let $\J = 4\T\kappa/\nu$. Then, with probability $1-\delta\pi^2/6$, we have that $\xb_{\T_1:\T+\J}$ converges $R$-linearly, $\xb_{\T:\T+\J}\in \N_{\nu}$, and
\begin{equation*}
\|\xb_{\T+\J +t +1} - \ttxb\|_{\ttHb} \leq 12 \rho_t\|\xb_{\T+\J +t} - \ttxb\|_{\ttHb}, \quad \forall t\geq 0
\end{equation*}
with
\begin{equation*}
\rho_t = \frac{4\T\kappa}{\T+\J+t+1} + 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}}
\end{equation*}
satisfying $24\rho_t\leq 1$, $\forall t\geq 0$.

\end{theorem}

