\begin{lemma}\label{lem:pre}
Let $d\geq 1$ and $\delta\in(0,1)$. If $d/\delta\geq e$, then for any $0<a\leq 1$,
\begin{equation*}
t\geq \frac {2\log(d/(\delta a))}{a}\quad\Longrightarrow\quad\frac{\log(dt/\delta)}{t} \leq a,
\end{equation*}
and moreover, the right hand side inequality fails if $t= \log(d/(\delta a))/a$ and $d/\delta >e$.
\end{lemma}

\begin{proof}
Let $t = 2\log(d/(\delta a))/a$. We will show for this $t$ that $t\geq \log(dt/\delta)/a$. We have
\begin{align*}
t - \frac{\log(dt/\delta)}{a}
& =  \frac{2\log(d/(\delta a))}{a} - \frac{\log(d/(\delta a)) + \log(2\log(d/(\delta a)))}{a}
\\
&=\frac{\log(d/(\delta a)) - \log(2\log(d/(\delta a)))}{a}\\
&= \frac1a\log\Big(\frac{x}{2\log(x)}\Big)\geq 0,\qquad\text{for}\quad x=\frac{d}{\delta a},
\end{align*}
where the last step is due to the fact that $x\geq 2\log(x)$ for all $x>0$. Now, we consider the function $f(t) = \log(dt/\delta)/t$. For any $t\geq1$, its derivative is bounded as
\begin{align*}
\frac{\partial f(t)}{\partial t} = \frac{1-\log(dt/\delta)}{t^2}\leq 0,
\end{align*}
which implies that for $t\geq2\log(d/(\delta a))/a \geq 1$ we get $\log(dt/\delta)/t =f(t)\leq f(2\log(d/(\delta a))/a)\leq a$. Finally, if $t=\log(d/(\delta a))/a$ and $d/\delta >e$, then $\log(dt/\delta)/a=\log(d/(\delta a))/a + \log(\log(d/(\delta a)))/a >t$, which completes the proof.
\end{proof}

\begin{lemma}\label{lem:pre:1}
Define the neighborhood $\bar{\N}_{\nu} = \{\xb: f(\xb) \leq f(\ttxb) + \nu\lambda_{\min}^3/L^2\}$ for $\nu>0$. Suppose Assumption \ref{ass:4} holds, then the following relation holds
\begin{equation*}
\bar{\N}_{\nu^2/3} \subseteq \N_{\nu} \subseteq \bar{\N}_{\nu^2}, \quad \text{for any } \nu \in (0, 1]
\end{equation*}
where $\N_{\nu}$ is defined in \eqref{Nnu}.	
\end{lemma}

\begin{proof}
By Assumption \ref{ass:4}, we have
\begin{equation}\label{pequ:A3}
\abr{f(\xb) - f(\ttxb) - \frac{1}{2}\nbr{\xb - \ttxb}_{\ttHb}^2} \leq \frac{L}{6}\nbr{\xb - \ttxb}^3.
\end{equation}
Suppose $\xb \in \bar{\N}_{\nu^2/3}$ for $\nu\in(0, 1]$, we have
\begin{equation}\label{pequ:A4}
f(\ttxb) + \frac{\lambda_{\min}}{2}\|\xb - \ttxb\|^2\leq f(\xb) \leq f(\ttxb) + \frac{\nu^2\lambda_{\min}^3}{3L^2} \Longrightarrow \|\xb - \ttxb\| \leq \frac{\sqrt{2}\nu\lambda_{\min}}{\sqrt{3}L}.
\end{equation}
Combining \eqref{pequ:A3} and \eqref{pequ:A4}, we know that $\xb \in \bar{\N}_{\nu^2/3}$ for $\nu\in(0, 1]$ leads to
\begin{align*}
f(\ttxb) + \frac{\nu^2\lambda_{\min}^3}{3L^2} \geq f(\xb) & \stackrel{\mathclap{\eqref{pequ:A3}}}{\geq} f(\ttxb) + \frac{1}{2}\|\xb - \ttxb\|_{\ttHb}^2 - \frac{L}{6}\|\xb-\ttxb\|^3	\\
& \geq f(\ttxb) + \frac{1}{2}\nbr{\xb - \ttxb}_{\ttHb}^2 - \frac{L}{6}\nbr{\xb - \ttxb}\cdot \frac{\nbr{\xb - \ttxb}_{\ttHb}^2}{\lambda_{\min}}\\
& = f(\ttxb) + \rbr{\frac{1}{2}-\frac{L\|\xb - \ttxb\|}{6\lambda_{\min}}}\|\xb - \ttxb\|_{\ttHb}^2\\
& \stackrel{\mathclap{\eqref{pequ:A4}}}{\geq} f(\ttxb) + \rbr{\frac{1}{2} - \frac{\sqrt{2}\nu}{6\sqrt{3}}}\|\xb - \ttxb\|_{\ttHb}^2 \geq f(\ttxb) + \frac{\|\xb - \ttxb\|_{\ttHb}^2}{3},
\end{align*}
which further implies $\|\xb - \ttxb\|_{\ttHb} \leq \nu\lambda_{\min}^{3/2}/L$ and $\xb\in \N_{\nu}$. On the other hand, suppose $\xb \in \N_{\nu}$, we have
\begin{align*}
f(\xb)  &\stackrel{\mathclap{\eqref{pequ:A3}}}{\leq} f(\ttxb) + \frac{1}{2}\nbr{\xb - \ttxb}_{\ttHb}^2 + \frac{L}{6}\nbr{\xb - \ttxb}^3 \leq f(\ttxb) + \rbr{ \frac{1}{2} + \frac{L\nbr{\xb - \ttxb}_{\ttHb}}{6\lambda_{\min}^{3/2}}} \nbr{\xb - \ttxb}_{\ttHb}^2\\
& \leq f(\ttxb) + \rbr{ \frac{1}{2} + \frac{\nu}{6}} \nbr{\xb - \ttxb}_{\ttHb}^2\leq f(\ttxb)  + \nbr{\xb - \ttxb}_{\ttHb}^2 \leq f(\ttxb) + \frac{\nu^2\lambda_{\min}^3}{L^2}.
\end{align*}
Thus, we have $\xb \in \bar{\N}_{\nu^2}$. This completes the proof.
\end{proof}

\begin{lemma}\label{lem:pre:2}
	Suppose Assumption \ref{ass:4} holds, then we have
	\begin{equation*}
		\|\Hb(\xb_1)^{-1/2}\Hb(\xb_2)\Hb(\xb_1)^{-1/2} - \Ib\| \leq \frac{L}{\lambda_{\min}^{3/2}}\|\xb_1 - \xb_2\|_{\ttHb}, \quad \forall \xb_1, \xb_2\in \mR^d.
	\end{equation*}
\end{lemma}

\begin{proof}
We note that
\begin{equation*}
\|\Hb(\xb_1)^{-1/2}\Hb(\xb_2)\Hb(\xb_1)^{-1/2} - \Ib\|  \leq \frac{1}{\lambda_{\min}}\|\Hb(\xb_1) - \Hb(\xb_2)\| \leq \frac{L}{\lambda_{\min}}\|\xb_1 - \xb_2\| \leq \frac{L}{\lambda_{\min}^{3/2}}\|\xb_1 - \xb_2\|_{\ttHb}.
\end{equation*}
This completes the proof.
\end{proof}

\subsection{Proof of Theorem \ref{thm:2}}\label{pf:thm:2}

For any $t\geq 0$ and scalar $\theta>0$, we have from Assumption \ref{ass:3} that
\begin{align*}
\mE_i\sbr{\exp\rbr{\theta z_{i,t}\Eb_i}}  & = \Ib + \theta z_{i,t}\mE_i[\Eb_i] + \sum_{j=2}^{\infty} \frac{(\theta z_{i,t})^j\mE_i[\Eb_i^j]}{j!}
\preceq \Ib + \sum_{j=2}^{\infty}(\theta z_{i,t}\Upsilon_E)^{j-2}\cdot \frac{(\theta z_{i,t}\Upsilon_E)^2}{2}\cdot\Ib \\
& = \Ib + \frac{(\theta z_{i,t}\Upsilon_E)^2}{2(1 - \theta z_{i,t} \Upsilon_E)}\cdot \Ib \preceq\exp\rbr{ \frac{(\theta z_{i,t}\Upsilon_E)^2}{2(1 - \theta z_{i,t}\Upsilon_E)} \cdot \Ib}, \quad \forall i = 0,1,\ldots,t,
\end{align*}
where the second equality holds for $\cbr{\theta: \theta z_{i,t}\Upsilon_E < 1}$. Therefore, we let $\Theta_t \coloneqq\{\theta: \theta < 1/(z_t^{(\max)}\Upsilon_E )\}$, and have for all $i = 0,1,\ldots, t$,
\begin{equation*}
\mE_i\sbr{\exp\rbr{\theta z_{i,t}\Eb_i}}  \preceq \exp\rbr{\frac{(\theta z_{i,t}\Upsilon_E)^2}{2(1 - \theta z_t^{(\max)} \Upsilon_E) } \cdot \Ib}, \quad \forall\theta\in \Theta_t.
\end{equation*}
The above inequality suggests that the condition \eqref{equ:exp:cond} in Lemma \ref{lem:2} holds with
\begin{equation*}
g_t(\theta) = \frac{\theta^2}{2(1 - \theta z_t^{(\max)} \Upsilon_E) }\quad \text{ and }\quad \Ub_i = z_{i,t}^2\Upsilon_E^2\cdot \Ib.
\end{equation*}
Let $\sigma^2 = \|\sum_{i=0}^{t}\Ub_i\| = \Upsilon_E^2\sum_{i=0}^{t}z_{i,t}^2$ in Lemma \ref{lem:2}. Then we have for any $\eta\geq 0$,
\begin{equation*}
\mP\rbr{\nbr{\barEb_t} \geq \eta} \leq 2d\cdot \inf_{\theta \in \Theta_t}\exp\rbr{-\theta\eta + g_t(\theta)\sigma^2}.
\end{equation*}
Plugging $\theta = \eta/(z_t^{(\max)} \Upsilon_E \eta + \sigma^2) \in \Theta_t$ into the above right hand side, we obtain
\begin{equation*}
\mP\rbr{\|\barEb_t\| \geq \eta} \leq 2d\cdot\exp\rbr{-\frac{\eta^2/2}{ \sigma^2 + z_t^{(\max)} \Upsilon_E \eta}  }.
\end{equation*}
This completes the proof.


\subsection{Proof of Lemma \ref{lem:3}}\label{pf:lem:3}

Let us define the event
\begin{equation*}
\bar{\EE} = \bigcap_{t=0}^{\infty}\cbr{\nbr{\barEb_t} \leq 8\Upsilon_E\rbr{\sqrt{\frac{\log(d(t+1)/\delta)}{t+1}}\vee \frac{\log(d(t+1)/\delta)}{t+1} } }.
\end{equation*}
By Theorem \ref{thm:2} and \eqref{equ:equal:con}, we know $\mP(\bar{\EE}) \geq 1-\delta\pi^2/6$. We also note that
\begin{align}\label{nequ:1}
\|\barEb_t\|\leq \epsilon\lambda_{\min} & \Longleftarrow 8\Upsilon_E\rbr{\sqrt{\frac{\log(d(t+1)/\delta)}{t+1}}\vee \frac{\log(d(t+1)/\delta)}{t+1} } \leq \epsilon\lambda_{\min} \nonumber\\
& \Longleftarrow \frac{\log(d(t+1)/\delta)}{t+1} \leq \frac{\epsilon^2}{64\Upsilon^2} \wedge1 = \rbr{\frac{\epsilon}{8\Upsilon}\wedge 1}^2 \nonumber\\
&\Longleftarrow t \geq 4\rbr{\frac{8\Upsilon}{\epsilon}\vee 1}^2 \log\cbr{\frac{d}{\delta}\cdot\rbr{\frac{8\Upsilon}{\epsilon}\vee 1}}=\T_1. \quad (\text{Lemma \ref{lem:pre}})
\end{align}
Therefore, with probability at least $1-\delta\pi^2/6$, we have for any $t\geq \T_1$ that $\|\barEb_t\|\leq \epsilon\lambda_{\min}$. This shows that the event $\EE$ defined in \eqref{event:EE} happens, and
\begin{equation*}
(1-\epsilon)\lambda_{\min}\cdot\Ib\preceq\tHb_t \stackrel{\eqref{equ:simple}}{=} \frac{1}{t+1}\sum_{i=0}^{t}\Hb_i + \barEb_t \preceq (\lambda_{\max} + \epsilon\lambda_{\min})\cdot\Ib\preceq (1+\epsilon)\lambda_{\max} \cdot\Ib.
\end{equation*}
This completes the proof.


\subsection{Proof of Lemma \ref{lem:4}}\label{pf:lem:4}

By Lemma \ref{lem:3}, we know that $\pb_t = -(\tHb_t)^{-1}\nabla f_t$ for $t\geq \T_1$. We apply Taylor's expansion:
\begin{align*}
	f(\xb_t - \mu_t(\tHb_t)^{-1}\nabla f_t ) & \leq f(\xb_t) - \mu_t \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t + \frac{\lambda_{\max}\mu_t^2}{2}\nabla f_t^\top(\tHb_t)^{-2}\nabla f_t \\
	& \leq f(\xb_t) - \mu_t \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t +\frac{\kappa\mu_t^2}{2(1-\epsilon)}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \quad (\text{Lemma \ref{lem:3}})\\
	& =  f(\xb_t) - \mu_t\rbr{1 - \frac{\kappa\mu_t}{2(1-\epsilon)}}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t.
\end{align*}
Thus, the Armijo condition is satisfied if
\begin{equation*}
1 - \frac{\kappa\mu_t}{2(1-\epsilon)} \geq \beta \Longleftrightarrow \mu_t \leq \frac{2(1-\beta)(1-\epsilon)}{\kappa}.
\end{equation*}
Therefore, the backtracking line search on Line 7 leads to a stepsize satisfying
\begin{equation}\label{npequ:1}
\mu_t\geq \frac{2\rho(1-\beta)(1-\epsilon)}{\kappa}.
\end{equation}
Moreover, we apply Lemma \ref{lem:3} and strong convexity of $f$, and have
\begin{equation}\label{npequ:2}
\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \geq \frac{1}{(1+\epsilon)\lambda_{\max}}\|\nabla f_t\|^2 \geq \frac{2}{(1+\epsilon)\kappa}(f(\xb_t) - f(\ttxb)).
\end{equation}
Combining \eqref{npequ:1}, \eqref{npequ:2} with the Armijo condition, we have
\begin{align}\label{pequ:B1}
f(\xb_{t+1}) - f(\ttxb) &\leq f(\xb_t) - f(\ttxb) - \mu_t \beta \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \nonumber\\
& \leq f(\xb_t) - f(\ttxb) - \frac{2\rho\beta(1-\beta)(1-\epsilon)}{\kappa}\cdot \frac{2}{(1+\epsilon)\kappa}(f(\xb_t) - f(\ttxb)) \nonumber\\
& = (1-\phi)(f(\xb_t) - f(\ttxb)),
\end{align}
which shows the first part of the statement. Furthermore, we apply \eqref{pequ:B1} recursively, apply strong convexity, and have
\begin{equation*}
\|\xb_t - \ttxb\|^2\leq \frac{2(f(\xb_t)-f(\ttxb))}{\lambda_{\min}} \\
\stackrel{\eqref{pequ:B1}}{\leq} \frac{2(1-\phi)^{t-\T_1}}{\lambda_{\min}}(f(\xb_{\T_1}) - f(\ttxb)) \leq \frac{2(1-\phi)^{t-\T_1}}{\lambda_{\min}}(f(\xb_0) - f(\ttxb)).
\end{equation*}
The last statement follows from $\|\xb_t-\ttxb\|_{\ttHb}^2\leq \lambda_{\max}\|\xb_t - \ttxb\|^2$. This completes the proof.


\subsection{Proof of Corollary \ref{cor:1}}\label{pf:cor:1}

We condition on the event \eqref{event:EE}, which happens with probability $1-\delta\pi^2/6$. By Lemma \ref{lem:4}, we know that, for $t\geq \T_1$,
\begin{equation*}
f(\xb_t) - f(\ttxb) \leq (1 - \phi)^{t-\T_1}(f(\xb_{\T_1}) - f(\ttxb)) \leq (1 - \phi)^{t-\T_1}(f(\xb_0) - f(\ttxb)).
\end{equation*}
By Lemma \ref{lem:pre:1}, to have $\xb_t \in \N_\nu$, it suffices to have $\xb_t \in \bar{\N}_{\nu^2/3}$. Thus, we let
\begin{equation}\label{equ:new}
(1 - \phi)^{t-\T_1}(f(\xb_0) - f(\ttxb)) \leq \frac{\nu^2\lambda_{\min}^3}{3L^2} \Longleftarrow t-\T_1 \geq \frac{\log\rbr{\frac{3L^2(f(\xb_0) - f(\ttxb))}{\nu^2\lambda_{\min}^3}}}{\log\rbr{\frac{1}{1-\phi}}}\Longleftarrow t \geq \T_1 + \T_2,
\end{equation}
where $\T_2$ is defined in \eqref{T2} and the implication uses the fact that $\log(1/(1-\phi))\geq \phi$. Furthermore, since $f(\xb_t)$ is always decreasing, we know after $\T_1+T_2$ iterations $\xb_t$ stays in $\bar{\N}_{\nu^2/3}$, and hence stays in $\N_{\nu}$ (cf. Lemma \ref{lem:pre:1}). This completes the proof.


\subsection{Proof of Lemma \ref{lem:5}}\label{pf:lem:5}

It suffices to show 
\begin{equation*}
f(\xb_t - (\tHb_t)^{-1}\nabla f_t) \leq f(\xb_t) - \beta\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t.
\end{equation*}
By Assumption \ref{ass:4}, we have
\begin{align}\label{npequ:3}
& f(\xb_t - (\tHb_t)^{-1}\nabla f_t) \nonumber\\
& \leq f(\xb_t) - \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t + \frac{1}{2}\nabla f_t^\top (\tHb_t)^{-1}\Hb_t(\tHb_t)^{-1}\nabla f_t + \frac{L}{6}\|(\tHb_t)^{-1}\nabla f_t\|^3 \nonumber\\
& \leq f(\xb_t) - \frac{1}{2}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t + \frac{1}{2}\nabla f_t^\top(\tHb_t)^{-1}(\Hb_t - \tHb_t)(\tHb_t)^{-1}\nabla f_t + \frac{L}{6}\|(\tHb_t)^{-1}\nabla f_t\|^3 \nonumber\\
& \leq f(\xb_t) - \frac{1}{2}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t + \frac{1}{2}\|(\tHb_t)^{-1/2}(\Hb_t - \tHb_t)(\tHb_t)^{-1/2}\|\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \nonumber\\
& \quad + \frac{L}{6}\|(\tHb_t)^{-1}\nabla f_t\| \nabla f_t^\top(\tHb_t)^{-2}\nabla f_t \nonumber\\
& \leq f(\xb_t) - \frac{1}{2}\nabla f_t^\top (\tHb_t)^{-1}\nabla f_t + \frac{\psi}{2(1-\psi)}\nabla f_t^\top (\tHb_t)^{-1}\nabla f_t + \frac{L\|(\tHb_t)^{-1}\nabla f_t\|}{6(1-\psi)\lambda_{\min}}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \nonumber\\
& = f(\xb_t) - \rbr{\frac{1}{2} - \frac{\psi}{2(1-\psi)} - \frac{L\|(\tHb_t)^{-1}\nabla f_t\|}{6(1-\psi)\lambda_{\min}}}\nabla f_t^\top (\tHb_t)^{-1}\nabla f_t.
\end{align}
For term $\|(\tHb_t)^{-1}\nabla f_t\|$, we let $\Hb_t^\eta = \Hb(\xb_t^\eta)$ with $\xb_t^\eta = \ttxb + \eta(\xb_t - \ttxb)$ for some $\eta\in(0, 1)$, and have
\begin{align}\label{npequ:4}
&\|(\tHb_t)^{-1}\nabla f_t\|^2  = (\xb_t - \ttxb)^\top (\ttHb)^{1/2}(\ttHb)^{-1/2}\Hb_t^\eta(\tHb_t)^{-2}\Hb_t^\eta(\ttHb)^{-1/2}(\ttHb)^{1/2}(\xb_t-\ttxb) \nonumber\\
& \leq \frac{\|\xb_t - \ttxb\|_{\ttHb}^2}{(1-\psi)\lambda_{\min}}\|(\ttHb)^{-1/2}\Hb_t^\eta(\tHb_t)^{-1}\Hb_t^\eta(\ttHb)^{-1/2}\| \nonumber\\
& \leq \frac{\nu^2\lambda_{\min}^2}{(1-\psi)L^2}\|(\ttHb)^{-1/2}(\Hb_t^\eta)^{1/2}\|^2\|(\Hb_t^\eta)^{1/2}(\tHb_t)^{-1}(\Hb_t^\eta)^{1/2}\| \quad (\text{since } \xb_t\in \N_{\nu}) \nonumber\\
& \leq \frac{\nu^2\lambda_{\min}^2}{(1-\psi)L^2}\|(\ttHb)^{-1/2}\Hb_t^\eta(\ttHb)^{-1/2}\|\|(\Hb_t^\eta)^{1/2}(\Hb_t)^{-1}(\Hb_t^\eta)^{1/2}\|\|\Hb_t^{1/2}(\tHb_t)^{-1}\Hb_t^{1/2}\| \nonumber\\
& \leq \frac{\nu^2\lambda_{\min}^2}{(1-\psi)^2L^2}\|(\ttHb)^{-1/2}\Hb_t^\eta(\ttHb)^{-1/2}\| \|(\Hb_t)^{-1/2}\Hb_t^\eta(\Hb_t)^{-1/2}\|.
\end{align}
Noting that $\xb_t^\eta\in\N_{\nu}$ if $\xb_t \in \N_\nu$, we apply Lemma \ref{lem:pre:2} and have
\begin{equation}\label{npequ:5}
\|(\ttHb)^{-1/2}\Hb_t^\eta(\ttHb)^{-1/2}\| \vee \|(\Hb_t)^{-1/2}\Hb_t^\eta(\Hb_t)^{-1/2}\| \leq 1 + \nu\leq 2.
\end{equation}
Combining \eqref{npequ:3}, \eqref{npequ:4}, and \eqref{npequ:5}, we finally obtain
\begin{equation*}
f(\xb_t - (\tHb_t)^{-1}\nabla f_t) \leq f(\xb_t) - \rbr{\frac{1}{2} - \frac{\psi}{2(1-\psi)} - \frac{\nu}{3(1-\psi)^2}}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t.
\end{equation*}
Thus, it suffices to let
\begin{equation*}
\frac{1}{2} - \frac{\psi}{2(1-\psi)} - \frac{\nu}{3(1-\psi)^2} \geq \beta \Longleftarrow \frac{\psi}{2(1-\psi)} \vee \frac{\nu}{3(1-\psi)^2} \leq \frac{1}{2}\rbr{\frac{1}{2}-\beta}
\end{equation*}
as implied by the conditions stated in the lemma. This completes the proof.



\subsection{Proof of Lemma \ref{lem:6}}\label{pf:lem:6}

Since $\xb_t\in \N_{\nu}$ with $\nu \leq 2/3\cdot (0.5-\beta)$, we apply Lemma \ref{lem:pre:2} and have
\begin{equation*}
\|(\ttHb)^{-1/2}(\Hb_t - \ttHb)(\ttHb)^{-1/2}\| \leq \frac{L}{\lambda_{\min}^{3/2}}\|\xb_t - \ttxb\|_{\ttHb} \leq \nu\leq 0.5-\beta.
\end{equation*}
Thus, we obtain
\begin{equation}\label{pequ:B2}
\rbr{0.5+\beta}\ttHb\preceq \Hb_t\preceq \rbr{1.5-\beta}\ttHb. 
\end{equation}
Since $\pb_t = -(\tHb_t)^{-1}\nabla f_t$ and $\mu_t=1$, we have
\begin{align}\label{npequ:6}
& \nbr{\xb_{t+1} - \ttxb}_{\ttHb} = \|\xb_t - (\tHb_t)^{-1}\nabla f_t - \ttxb\|_{\ttHb} \nonumber\\
& \stackrel{\mathclap{\eqref{pequ:B2}}}{\leq}\frac{1}{\sqrt{0.5+\beta}}\|\xb_t - (\tHb_t)^{-1}\nabla f_t - \ttxb\|_{\Hb_t} \nonumber\\
& \leq \frac{1}{\sqrt{0.5+\beta}}\cbr{\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} + \|\Hb_t^{-1}\nabla f_t - (\tHb_t)^{-1}\nabla f_t\|_{\Hb_t}}.
\end{align}
For the second term on the right hand side, we have
\begin{align}\label{npequ:7}
& \|\Hb_t^{-1}\nabla f_t - (\tHb_t)^{-1}\nabla f_t\|_{\Hb_t} \nonumber\\
& = \sqrt{\nabla f_t^\top(\Hb_t^{-1} - (\tHb_t)^{-1})\Hb_t(\Hb_t^{-1} - (\tHb_t)^{-1})\nabla f_t} \nonumber\\
& = \sqrt{\nabla f_t^\top\Hb_t^{-1/2}(\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2})^2\Hb_t^{-1/2}\nabla f_t} \nonumber\\
& \leq \|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\|\cdot\|\Hb_t^{-1}\nabla f_t\|_{\Hb_t}  \nonumber\\
& \leq  \|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\|\cbr{\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} + \|\xb_t - \ttxb\|_{\Hb_t}} \nonumber\\
& \stackrel{\mathclap{\eqref{pequ:B2}}}{\leq}\|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\|\cbr{\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} + \sqrt{1.5-\beta}\|\xb_t - \ttxb\|_{\ttHb}}.
\end{align}
Combining \eqref{npequ:6} and \eqref{npequ:7},
\begin{align}\label{pequ:B3}
\|\xb_{t+1} - \ttxb\|_{\ttHb}& \leq\frac{1}{\sqrt{0.5+\beta}} \big\{(1+\|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\|)\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} \nonumber\\
& \quad + \sqrt{1.5-\beta}\|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\|\cdot \|\xb_t - \ttxb\|_{\ttHb}\big\}.
\end{align}
Since $\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| \leq \psi\leq 1/3$, we have
\begin{equation*}
(1 - \|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| )\cdot \Ib \preceq \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2} \preceq (1+\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\|)\cdot\Ib
\end{equation*}
and further
\begin{equation*}
-\frac{\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }{1+\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }\cdot \Ib\preceq \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2} - \Ib \preceq \frac{\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }{1-\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }\cdot\Ib.
\end{equation*}
Thus, we have
\begin{equation*}
\|\Ib - \Hb_t^{1/2}(\tHb_t)^{-1} \Hb_t^{1/2}\| \leq \frac{\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }{1 - \|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\| }\leq \frac{3}{2}\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\|.
\end{equation*}
Combining the above inequality with \eqref{pequ:B3}, we obtain
\begin{align}\label{pequ:B4}
&\|\xb_{t+1} - \ttxb\|_{\ttHb} \nonumber\\
&  \leq \frac{3}{2\sqrt{0.5+\beta}} \|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} + \frac{3}{2}\sqrt{\frac{1.5-\beta}{0.5+\beta}}\cdot\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\|  \cdot \|\xb_t - \ttxb\|_{\ttHb} \nonumber\\
& \leq \frac{3\sqrt{2}}{2}\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t}  + \frac{3\sqrt{3}}{2}\|\Ib - \Hb_t^{-1/2}\tHb_t \Hb_t^{-1/2}\|  \cdot \|\xb_t - \ttxb\|_{\ttHb}.
\end{align}
Furthermore,
\begin{align*}
\|\xb_t - \Hb_t^{-1}\nabla f_t - \ttxb\|_{\Hb_t} & = \|\Hb_t^{-1/2}(\Hb_t(\xb_t - \ttxb) - \nabla f_t)\|\\
& \leq \frac{1}{\sqrt{\lambda_{\min}}}\nbr{\Hb_t(\xb_t - \ttxb) - \rbr{\int_0^1\Hb(\ttxb + \tau(\xb_t - \ttxb))d\tau }(\xb_t-\ttxb)}\\
& \leq \frac{\|\xb_t -\ttxb\|^2}{\sqrt{\lambda_{\min}}}\cdot \int_0^1(1-\tau)L d\tau \leq \frac{L}{2\lambda_{\min}^{3/2}}\|\xb_t-\ttxb\|_{\ttHb}^2.
\end{align*}
Combining the above inequality with \eqref{pequ:B4}, we complete the proof.



\subsection{Proof of Theorem \ref{thm:3}}\label{pf:thm:3}

We suppose the event \eqref{event:EE} happens, which has probability $1-\delta\pi^2/6$. By Lemma \ref{lem:4} and Corollary \ref{cor:1}, we know that $\xb_t$ converges $R$-linearly for all $t\geq \T_1$, and $\xb_{\T:\T+\J}\in \N_{\nu}$ for any $\J\geq 0$.~Thus, it suffices to study the convergence after $\T+\J$. For any $t\geq 0$, to apply Lemmas \ref{lem:5} and \ref{lem:6}, we characterize the difference between $\tHb_{\T+\J+t}$ and $\Hb_{\T+\J+t}$. We have
\begin{align}\label{npequ:8}
& \|\Hb_{\T+\J + t}^{-1/2}\tHb_{\T+\J + t}\Hb_{\T+\J + t}^{-1/2} -\Ib\|  \nonumber\\
& \leq \|\Hb_{\T+\J + t}^{-1/2}(\tHb_{\T+\J + t} - \ttHb)\Hb_{\T+\J + t}^{-1/2}\| + \|\Hb_{\T+\J + t}^{-1/2}\ttHb\Hb_{\T+\J + t}^{-1/2} - \Ib\| \nonumber\\
& \stackrel{\mathclap{\text{Lemma \ref{lem:pre:2}}}}{\leq}\;\;\; \|\Hb_{\T+\J + t}^{-1/2}(\tHb_{\T+\J + t} - \ttHb)\Hb_{\T+\J + t}^{-1/2}\|  + \frac{L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t} - \ttxb\|_{\ttHb}. 
\end{align}
For the first term $\|\Hb_{\T+\J + t}^{-1/2}(\tHb_{\T+\J + t} - \ttHb)\Hb_{\T+\J + t}^{-1/2}\|$, we apply the formula \eqref{equ:simple} and have
\begin{align}\label{npequ:9}
&\|\Hb_{\T+\J + t}^{-1/2}(\tHb_{\T+\J + t} - \ttHb)\Hb_{\T+\J + t}^{-1/2}\| \nonumber\\
& \stackrel{\mathclap{\eqref{equ:simple}}}{\leq} \frac{1}{\lambda_{\min}}\nbr{\barEb_{\T+\J+t}}  + \frac{1}{\T+\J + t + 1}\bigg\{\sum_{j=0}^{\T-1}\|\Hb_{\T+\J + t}^{-1/2}(\Hb_j - \ttHb)\Hb_{\T+\J + t}^{-1/2}\| \nonumber\\
&\hskip6cm + \sum_{j=\T}^{\T+\J+t}\|\Hb_{\T+\J + t}^{-1/2}(\Hb_j - \ttHb)\Hb_{\T+\J + t}^{-1/2}\| \bigg\} \nonumber\\
& \leq \frac{1}{\lambda_{\min}}\|\barEb_{\T+\J+t}\| + \frac{2\T\kappa}{\T+\J+t+1} + \frac{L}{\lambda_{\min}(\T+\J+t+1)}\sum_{j=\T}^{\T+\J+t}\|\xb_j - \ttxb\| \nonumber\\
& \stackrel{\mathclap{\eqref{event:EE}}}{\leq} 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}} + \frac{2\T\kappa}{\T+\J+t+1} \nonumber\\ 
&\hskip0.5cm +\frac{L}{\lambda_{\min}(\T+\J+t+1)}\sum_{j=\T}^{\T+\J+t}\sqrt{\frac{2(f(\xb_0) - f(\ttxb))}{\lambda_{\min}}}(1 - \phi)^{(j-\T_1)/2} \quad (\text{also use Lemma \ref{lem:4}}) \nonumber\\
& \leq 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}} + \frac{2\T\kappa}{\T+\J+t+1} + \frac{L\sqrt{2(f(\xb_0) - f(\ttxb))}}{\lambda_{\min}^{3/2}(\T+\J+t+1)}(1-\phi)^{\T_2/2}\sum_{j=0}^{\infty}(1-\phi)^{j/2} \nonumber\\
& \stackrel{\mathclap{\eqref{equ:new}}}{\leq}\; 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}} + \frac{2\T\kappa}{\T+\J+t+1} + \frac{\sqrt{2}\nu}{\sqrt{3}(\T+\J+t+1)(1-\sqrt{1-\phi})} \nonumber\\
& \leq 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}} + \frac{2\T\kappa}{\T+\J+t+1} + \frac{2\nu}{(\T+\J+t+1)\phi} \nonumber\\
& \leq 8\Upsilon\sqrt{\frac{\log(d(\T+\J+t+1)/\delta)}{\T+\J+t+1}} + \frac{4\T\kappa}{\T+\J+t+1} = \rho_t.\quad (\text{since } \nu/\phi \leq1/\phi\leq\T\kappa)
\end{align}
Combining \eqref{npequ:8} and \eqref{npequ:9} together, we obtain
\begin{equation}\label{pequ:B5}
\|\Hb_{\T+\J + t}^{-1/2}\tHb_{\T+\J + t}\Hb_{\T+\J + t}^{-1/2} -\Ib\|\leq \rho_t+\frac{L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t} - \ttxb\|_{\ttHb} \leq \rho_t + \nu\leq \rho_0 + \nu.
\end{equation}
Thus, in order to apply Lemma \ref{lem:6} for all $\{\xb_{\T+\J+t}\}_{t\geq 0}$, we require $\nu\leq 2/3\cdot (0.5-\beta)$ and
\begin{align*}
\rho_0 + \nu \leq \frac{0.5-\beta}{1.5-\beta} & \xLeftarrow{\J = 4\T\kappa/\nu} 8\Upsilon\sqrt{\frac{\log(d(\T+\J)/\delta)}{\T+\J}} + 2\nu \leq \frac{0.5-\beta}{1.5-\beta} \\
& \Longleftarrow 8\Upsilon\sqrt{\frac{\log(d(\T+\J)/\delta)}{\T+\J}}  \vee\nu\leq \frac{1}{3}\frac{0.5-\beta}{1.5-\beta}\\
& \stackrel{\eqref{cond:epsnu}}{\Longleftarrow} 8\Upsilon\sqrt{\frac{\log(d(\T+\J)/\delta)}{\T+\J}}  \leq \epsilon \; \text{ and }\; \epsilon\vee \nu \leq \frac{1}{3}\frac{0.5-\beta}{1.5-\beta},
\end{align*}
which is implied by \eqref{cond:epsnu} and \eqref{nequ:1}. Thus, for any $t\geq 0$, we apply Lemma \ref{lem:6} and obtain
\begin{align}\label{pequ:B6}
& \|\xb_{\T+\J+t+1}-\ttxb\|_{\ttHb} \nonumber\\
& \leq 3\cbr{\frac{L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t}-\ttxb\|_{\ttHb}^2 + \|\Hb_{\T+\J + t}^{-1/2}\tHb_{\T+\J + t}\Hb_{\T+\J + t}^{-1/2} -\Ib\|\cdot \|\xb_{\T+\J+t} - \ttxb\|_{\ttHb}} \nonumber\\
&\stackrel{\mathclap{\eqref{pequ:B5}}}{\leq} 3\cbr{\frac{2L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t}-\ttxb\|_{\ttHb}^2 +  \rho_t\|\xb_{\T+\J+t}-\ttxb\|_{\ttHb}}.
\end{align}
We then claim that
\begin{equation}\label{pequ:B7}
\frac{2L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t}-\ttxb\|_{\ttHb} \leq 3\rho_t, \quad \forall t\geq 0.
\end{equation}
We prove \eqref{pequ:B7} by induction. For $t = 0$, we note that
\begin{equation*}
\frac{2L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J}-\ttxb\|_{\ttHb} \leq 2\nu = \frac{12\T\kappa}{6\T\kappa/\nu}\leq \frac{12\T\kappa}{\T + 4\T\kappa/\nu +1} = \frac{12\T\kappa}{\T + \J +1} \leq 3\rho_0.
\end{equation*}
Suppose \eqref{pequ:B7} holds for $t\geq 0$, then \eqref{pequ:B6} leads to
\begin{equation*}
\frac{2L}{\lambda_{\min}^{3/2}}\|\xb_{\T+\J+t+1}-\ttxb\|_{\ttHb} \leq \frac{2L}{\lambda_{\min}^{3/2}}\cdot 12\rho_t\|\xb_{\T+\J+t}-\ttxb\|_{\ttHb} \stackrel{\eqref{pequ:B7}}{\leq} 36\rho_t^2.
\end{equation*}
On the other hand, using $(\T+\J+t+2)\leq 2(\T+\J+t+1)$, $\forall t\geq 0$, we know $\rho_t/2 \leq \rho_{t+1}$. Thus, it suffices to show $36\rho_t^2\leq 3\rho_t/2\Longleftrightarrow 24\rho_t\leq 1$. Since $\rho_t$ is decreasing, we require $24\rho_0\leq 1$. Note that
\begin{equation*}
\rho_0 \leq 8\Upsilon\sqrt{\frac{\log(d\T/\delta)}{\T}} + \nu \stackrel{\eqref{T2}}{\leq} \epsilon + \nu.
\end{equation*}
Thus, $24\rho_0\leq 1$ is guaranteed by \eqref{cond:epsnu}. Combining \eqref{pequ:B6} and \eqref{pequ:B7} completes the proof.

