\begin{lemma}\label{lem:pre}
Let $d\geq 1$ and $\delta\in(0,1)$. If $d/\delta\geq e$, then for any $0<a\leq 1$,
\begin{equation*}
t\geq \frac {2\log(d/(\delta a))}{a}\quad\Longrightarrow\quad\frac{\log(dt/\delta)}{t} \leq a,
\end{equation*}
and moreover, the right hand side inequality fails if $t= \log(d/(\delta a))/a$ and $d/\delta >e$.
\end{lemma}

\begin{proof}
Let $t = 2\log(d/(\delta a))/a$. We will show for this $t$ that $t\geq \log(dt/\delta)/a$. We have
\begin{align*}
t - \frac{\log(dt/\delta)}{a}
& =  \frac{2\log(d/(\delta a))}{a} - \frac{\log(d/(\delta a)) + \log(2\log(d/(\delta a)))}{a}
\\
&=\frac{\log(d/(\delta a)) - \log(2\log(d/(\delta a)))}{a}\\
&= \frac1a\log\Big(\frac{x}{2\log(x)}\Big)\geq 0,\qquad\text{for}\quad x=\frac{d}{\delta a},
\end{align*}
where the last step is due to the fact that $x\geq 2\log(x)$ for all $x>0$. Now, we consider the function $f(t) = \log(dt/\delta)/t$. For any $t\geq1$, its derivative is bounded as
\begin{align*}
\frac{\partial f(t)}{\partial t} = \frac{1-\log(dt/\delta)}{t^2}\leq 0,
\end{align*}
which implies that for $t\geq2\log(d/(\delta a))/a \geq 1$ we get $\log(dt/\delta)/t =f(t)\leq f(2\log(d/(\delta a))/a)\leq a$. Finally, if $t=\log(d/(\delta a))/a$ and $d/\delta >e$, then $\log(dt/\delta)/a=\log(d/(\delta a))/a + \log(\log(d/(\delta a)))/a >t$, which completes the proof.
\end{proof}

