The above inequality suggests that the condition \eqref{equ:exp:cond} in Lemma \ref{lem:2} holds with
\begin{equation*}
g_t(\theta) = \frac{\theta^2}{2(1 - \theta z_t^{(\max)} \Upsilon_E) }\quad \text{ and }\quad \Ub_i = z_{i,t}^2\Upsilon_E^2\cdot \Ib.
\end{equation*}
Let $\sigma^2 = \|\sum_{i=0}^{t}\Ub_i\| = \Upsilon_E^2\sum_{i=0}^{t}z_{i,t}^2$ in Lemma \ref{lem:2}. Then we have for any $\eta\geq 0$,
\begin{equation*}
\mP\rbr{\nbr{\barEb_t} \geq \eta} \leq 2d\cdot \inf_{\theta \in \Theta_t}\exp\rbr{-\theta\eta + g_t(\theta)\sigma^2}.
\end{equation*}

Plugging $\theta = \eta/(z_t^{(\max)} \Upsilon_E \eta + \sigma^2) \in \Theta_t$ into the above right hand side, we obtain
\begin{equation*}
\mP\rbr{\|\barEb_t\| \geq \eta} \leq 2d\cdot\exp\rbr{-\frac{\eta^2/2}{ \sigma^2 + z_t^{(\max)} \Upsilon_E \eta}  }.
\end{equation*}
This completes the proof.

\begin{lemma}[Adapted from Theorem 2.3 in \cite{Tropp2011Freedmans}]\label{lem:2}
Let $t\geq 0$ be a fixed integer. Consider a $d$-dimensional martingale difference $\{\Eb_i\}_{i=0}^{t}$ (i.e., $\mE_i[\Eb_i] = \0$). Suppose there exists a function $g_t:\Theta_t\rightarrow [0, \infty]$ with $\Theta_t\subseteq (0, \infty)$, and~a~sequence of matrices $\{\Ub_i\}_{i=0}^{t}$, such that for any $i = 0,1,\ldots,t$,\footnote{The matrix exponential is defined by power series expansion: $\exp(\Ab) = \Ib + \sum_{i=1}^{\infty} \Ab^i/ i!$.}
\begin{equation}\label{equ:exp:cond}
\mE_i\sbr{\exp\rbr{\theta\Eb_i}}\preceq \exp\rbr{g_t(\theta)\Ub_i} \quad \text{ almost surely for each } \theta\in \Theta_t.
\end{equation}
Then, we have for any scalars $\eta \geq 0$ and $\sigma^2>0$,
\begin{equation*}
\mP\rbr{\Big\|\sum_{i=0}^{t}\Eb_i\Big\| \geq \eta\; \text{ and } \; \Big\|\sum_{i=0}^{t}\Ub_i\Big\|\leq \sigma^2} \leq 2d\cdot \inf_{\theta\in \Theta_t}\exp\rbr{-\theta \eta + g_t(\theta)\sigma^2}.
\end{equation*}		
\end{lemma}

The martingale concentration in Theorem \ref{thm:2} matches the matrix Bernstein results for independent noises $\{\Eb_i\}_{i=0}^t$ \citep[cf. Theorems 6.1, 6.2 in][]{Tropp2011User}. For any~$\delta\in(0, 1)$, if we let the right hand side of \eqref{equ:subE} be $\delta/(t+1)^2$, then we obtain that, with probability at least $1 - \delta/(t+1)^2$,  
\begin{equation}\label{equ:sub:concen}
\small \nbr{\barEb_t} \leq 8\Upsilon_E\sqrt{\log\rbr{\frac{d(t+1)}{\delta}}}\rbr{\sqrt{\sum_{i=0}^{t}z_{i,t}^2} \; \vee \; \sqrt{\log\rbr{\frac{d(t+1)}{\delta}}} \cdot z_t^{(\max)}}.
\end{equation}

To achieve the fastest concentration rate, we minimize the right~hand side of \eqref{equ:sub:concen} under the~restriction $\sum_{i=0}^t z_{i,t} = 1$. Note that the minimum of both $\sum_{i=0}^t z_{i,t}^2$ and $z_t^{(\max)}$ is attained with equal weights, that is $z_{i,t} = 1/(t+1)$, for $ i = 0,1,\ldots, t$. Thus, the fastest concentration rate is attained~with~equal~weights. Furthermore, a union bound over $t$ leads to
\begin{equation}\label{equ:equal:con}
\mP\rbr{\forall t:\ \nbr{\barEb_t} \leq
8\Upsilon_E\bigg(\sqrt{\frac{\log(d(t+1)/\delta)}{t+1}} \vee
  \frac{\log(d(t+1)/\delta)}{t+1}\bigg)} 
\geq 1 - \sum_{t=0}^{\infty}
\frac{\delta}{(t+1)^2}= 1-\frac{\pi^2\delta}{6}.
\end{equation}

The martingale concentration in Theorem \ref{thm:2} matches the matrix Bernstein results for independent noises $\{\Eb_i\}_{i=0}^t$ \citep[cf. Theorems 6.1, 6.2 in][]{Tropp2011User}. For any~$\delta\in(0, 1)$, if we let the right hand side of \eqref{equ:subE} be $\delta/(t+1)^2$, then we obtain that, with probability at least $1 - \delta/(t+1)^2$,  
\begin{equation}\label{equ:sub:concen}
\small \nbr{\barEb_t} \leq 8\Upsilon_E\sqrt{\log\rbr{\frac{d(t+1)}{\delta}}}\rbr{\sqrt{\sum_{i=0}^{t}z_{i,t}^2} \; \vee \; \sqrt{\log\rbr{\frac{d(t+1)}{\delta}}} \cdot z_t^{(\max)}}.
\end{equation}

\begin{lemma}\label{lem:3}
Consider Algorithm \ref{alg:1} with $w_t = t+1$, $\forall t\geq 0$. Under Assumption~\ref{ass:3}, we let $\delta, \epsilon\in(0, 1)$ with $d/\delta\geq e$. We also let
\begin{equation}\label{T1}
\T_1 =4\rbr{1\vee (8\Upsilon/\epsilon)}^2 \log\rbr{d/\delta\cdot\cbr{1\vee(8\Upsilon/\epsilon)}}.
\end{equation}
Then, with probability $1-\delta\pi^2/6$, the event
\begin{equation}\label{event:EE}
\EE = \bigcap_{t=\T_1}^{\infty}\cbr{\|\barEb_t\| \leq 8\Upsilon_E\sqrt{\frac{\log(d(t+1)/\delta)}{t+1}}}
\end{equation}
occurs, which implies $(1-\epsilon)\lambda_{\min}\cdot\Ib\preceq \tHb_t \preceq (1+\epsilon)\lambda_{\max}\cdot\Ib$, $\forall t\geq \T_1$.
\end{lemma}

