\begin{lemma}\label{lem:4}
Conditioning on the event \eqref{event:EE}, we let
\begin{equation*}
\phi = \frac{4\rho\beta(1-\beta)(1-\epsilon)}{\kappa^2(1+\epsilon)}
\end{equation*}
and have $f(\xb_{t+1})-f(\ttxb) \leq (1-\phi)(f(\xb_t) - f(\ttxb))$, $\forall t\geq \T_1$, which implies $R$-linear convergence of the iterate error,
\begin{align*}
\|\xb_t - \ttxb\| &\leq \cbr{\frac{2}{\lambda_{\min}}(f(\xb_0) - f(\ttxb))(1-\phi)^{t-\T_1}}^{1/2}, \quad t\geq \T_1,\\
\|\xb_t - \ttxb\|_{\ttHb} &\leq \cbr{2\kappa(f(\xb_0) - f(\ttxb))(1-\phi)^{t-\T_1}}^{1/2}, \quad\quad\; t\geq \T_1.
\end{align*}
\end{lemma}

\begin{proof}
See Appendix \ref{pf:lem:4}.
\end{proof}

\subsection{Proof of Lemma \ref{lem:4}}\label{pf:lem:4}

By Lemma \ref{lem:3}, we know that $\pb_t = -(\tHb_t)^{-1}\nabla f_t$ for $t\geq \T_1$. We apply Taylor's expansion:
\begin{align*}
	f(\xb_t - \mu_t(\tHb_t)^{-1}\nabla f_t ) & \leq f(\xb_t) - \mu_t \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t + \frac{\lambda_{\max}\mu_t^2}{2}\nabla f_t^\top(\tHb_t)^{-2}\nabla f_t \\
	& \leq f(\xb_t) - \mu_t \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t +\frac{\kappa\mu_t^2}{2(1-\epsilon)}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \quad (\text{Lemma \ref{lem:3}})\\
	& =  f(\xb_t) - \mu_t\rbr{1 - \frac{\kappa\mu_t}{2(1-\epsilon)}}\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t.
\end{align*}
Thus, the Armijo condition is satisfied if
\begin{equation*}
1 - \frac{\kappa\mu_t}{2(1-\epsilon)} \geq \beta \Longleftrightarrow \mu_t \leq \frac{2(1-\beta)(1-\epsilon)}{\kappa}.
\end{equation*}
Therefore, the backtracking line search on Line 7 leads to a stepsize satisfying
\begin{equation}\label{npequ:1}
\mu_t\geq \frac{2\rho(1-\beta)(1-\epsilon)}{\kappa}.
\end{equation}
Moreover, we apply Lemma \ref{lem:3} and strong convexity of $f$, and have
\begin{equation}\label{npequ:2}
\nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \geq \frac{1}{(1+\epsilon)\lambda_{\max}}\|\nabla f_t\|^2 \geq \frac{2}{(1+\epsilon)\kappa}(f(\xb_t) - f(\ttxb)).
\end{equation}
Combining \eqref{npequ:1}, \eqref{npequ:2} with the Armijo condition, we have
\begin{align}\label{pequ:B1}
f(\xb_{t+1}) - f(\ttxb) &\leq f(\xb_t) - f(\ttxb) - \mu_t \beta \nabla f_t^\top(\tHb_t)^{-1}\nabla f_t \nonumber\\
& \leq f(\xb_t) - f(\ttxb) - \frac{2\rho\beta(1-\beta)(1-\epsilon)}{\kappa}\cdot \frac{2}{(1+\epsilon)\kappa}(f(\xb_t) - f(\ttxb)) \nonumber\\
& = (1-\phi)(f(\xb_t) - f(\ttxb)),
\end{align}
which shows the first part of the statement. Furthermore, we apply \eqref{pequ:B1} recursively, apply strong convexity, and have
\begin{equation*}
\|\xb_t - \ttxb\|^2\leq \frac{2(f(\xb_t)-f(\ttxb))}{\lambda_{\min}} \\
\stackrel{\eqref{pequ:B1}}{\leq} \frac{2(1-\phi)^{t-\T_1}}{\lambda_{\min}}(f(\xb_{\T_1}) - f(\ttxb)) \leq \frac{2(1-\phi)^{t-\T_1}}{\lambda_{\min}}(f(\xb_0) - f(\ttxb)).
\end{equation*}
The last statement follows from $\|\xb_t-\ttxb\|_{\ttHb}^2\leq \lambda_{\max}\|\xb_t - \ttxb\|^2$. This completes the proof.

