We consider minimizing a smooth and strongly convex objective function:
\begin{equation}\label{pro:1}
\min_{\xb\in \mR^d}\; f(\xb),
\end{equation}
where $f:\mR^d\rightarrow \mR$ is twice continuously differentiable with $\Hb(\xb) = \nabla^2 f(\xb) \in \mR^{d\times d}$ being its Hessian matrix. We suppose the Hessian $\Hb(\xb)$ satisfies
\begin{equation*}
\lambda_{\min}\cdot \Ib \preceq \Hb(\xb) \preceq\lambda_{\max}\cdot\Ib, \quad\;  \forall \xb\in\mR^d,
\end{equation*}
for some constants $0<\lambda_{\min}\leq\lambda_{\max}$, and we let $\kappa = \lambda_{\max}/\lambda_{\min}$ denote its~condition number. We also let $\xb^\star = \arg\min_{\xb\in \mR^d} f(\xb)$ be the unique global~solution.

\begin{equation}\label{equ:Newton}
\xb_{t+1} = \xb_t - \mu_t \Hb_t^{-1}\nabla f_t,
\end{equation}

A parallel line of research explores stochastic Newton methods, where a stochastic approximation $\hHb_t$ is used in place of $\Hb_t$ in \eqref{equ:Newton}. The stochasticity of $\hHb_t$ may come from evaluating the Hessian on a random subset of data points~(i.e., subsampling), or from projecting the Hessian onto a random subspace to~achieve~the dimension reduction (i.e., sketching). To unify different approaches, we consider in this paper a general Hessian approximation given by a \textit{stochastic oracle}. In particular, we express the approximation $\hHb(\xb)$ at any point $\xb$ by
\begin{equation}\label{equ:error}
\hHb(\xb) = \Hb(\xb) + \Eb(\xb),
\end{equation}

We consider an online averaging scheme (we let $\tHb_{-1} = \0$):
\begin{equation}\label{equ:ave:Hessian}
\tHb_t  = \frac{w_{t-1}}{w_t} \tHb_{t-1} + \rbr{1 - \frac{w_{t-1}}{w_t}}\hHb_t, \quad t = 0,1,2,\ldots,\\
\end{equation}

where $\{w_t\}_{t=-1}^{\infty}$ is a prespecified increasing non-negative weight sequence~starting with $w_{-1} = 0$. By \emph{online} we mean that we only keep an average Hessian $\tHb_t$ in each iteration, and update it as \eqref{equ:ave:Hessian} when we obtain a new Hessian estimate. This scheme is in contrast to keeping all the past Hessian estimates. By the scheme \eqref{equ:ave:Hessian}, we note that, at iteration $t$, we re-scale the weights of $\{\hHb_i\}_{t=0}^{t-1}$ equally by a factor of $w_{t-1}/w_t$, instead of completely redefining all the weights. We note that such an online averaging scheme is memory and computation efficient: compared to stochastic Newton methods without averaging, we only require an extra $O(d^2)$ space to save $\tHb_t$ and $O(d^2)$ flops to update it, which is negligible in the setting of stochastic Newton methods where the Hessian vector product requires $O(d^2)$ flops and solving the exact Newton system requires $O(d^3)$ flops. In \eqref{equ:ave:Hessian}, we use the ratio factors $w_{t-1}/w_t$ instead of direct weights merely to simplify our later presentation. Furthermore, \eqref{equ:ave:Hessian} can be reformulated as a general weighted average as follows:\vskip-0.32cm
\begin{equation}\label{equ:z}
\tHb_t =\sum_{i=0}^tz_{i,t}\hHb_i,\qquad\text{with}\quad
  z_{i,t}\coloneqq(w_i-w_{i-1})/w_t.
\end{equation}

\begin{algorithm}[!t]
\caption{Stochastic Newton Method with Hessian Averaging}
\label{alg:1}
\begin{algorithmic}[1]
\State \textbf{Input}: iterate $\xb_0$, weights $\{w_t\}_{t=-1}^{\infty}$, scalars $\beta\in(0, 1/2)$, $\rho\in(0, 1)$, and $\tHb_{-1} = \0$;
\For{ $t = 0,1,2,\ldots$}
\State Obtain a stochastic Hessian approximation $\hHb_t = \Hb_t + \Eb_t$;
\State Compute the Hessian average via \eqref{equ:ave:Hessian}: $\tHb_t  = \frac{w_{t-1}}{w_t} \tHb_{t-1} + \rbr{1 - \frac{w_{t-1}}{w_t}}\hHb_t$;
\State Compute the Newton direction $\pb_t$ by solving: $\tHb_t\pb_t = -\nabla f_t$;\vspace{1mm}
\State \textbf{if} $\tHb_t\pb_t = -\nabla f_t$ is not solvable \textbf{or} $\nabla f_t^\top\pb_t\geq 0$, \ \textbf{then} \ skip iteration with~$\xb_{t+1}=\xb_t$; 
\State Compute a stepsize $\mu_t = \rho^{j_t}$, where $j_t$ is the smallest nonnegative integer such that
\begin{equation*}
\text{Armijo condition}:\hskip 0.5cm f(\xb_t+\mu_t\pb_t) \leq f(\xb_t) + \mu_t\beta \nabla f_t^\top\pb_t
\end{equation*}
\State Update $\xb_{t+1} = \xb_t +\mu_t\pb_t$;
\EndFor
\end{algorithmic}
\end{algorithm}

For a given weight sequence $\{w_t\}_{t=-1}^\infty$ with $w_{-1}=0$, the scheme \eqref{equ:ave:Hessian} leads~to \vskip-0.4cm
\begin{equation}\label{equ:simple}
\tHb_t\;\; \stackrel{\mathclap{\eqref{equ:z}}}{=}\; \sum_{i=0}^{t}z_{i,t}\hHb_i \ \stackrel{\mathclap{\eqref{equ:error}}}{=} \!\!\underbrace{\sum_{i=0}^{t}z_{i,t}\Hb_i}_{\text{Hessian averaging}}\!\!+\!\!\quad\barEb_t\qquad\quad\text{for} \quad \barEb_t\coloneqq\!\!\underbrace{\sum_{i=0}^{t}z_{i,t}\Eb_i }_{\text{noise averaging}}
\end{equation}

\begin{assumption}[Sub-exponential noise]\label{ass:3}
We assume that  $\Eb(\xb)$ is mean zero and $\|\Eb(\xb)\|$ is $\Upsilon_E$-sub-exponential for all $\xb$. Also, we define $\Upsilon\coloneqq\Upsilon_E/\lambda_{\min}$ to be the scale-invariant noise level. 
\end{assumption}

\begin{assumption}[Lipschitz Hessian]\label{ass:4}
We assume $\Hb(\xb)$ is $L$-Lipschitz continuous. That is $\|\Hb(\xb_1) - \Hb(\xb_2)\|\leq L\|\xb_1 - \xb_2\|$ for any $\xb_1, \xb_2\in \mR^d$.
\end{assumption}

\begin{equation}\label{equ:equal:con}
\mP\rbr{\forall t:\ \nbr{\barEb_t} \leq
8\Upsilon_E\bigg(\sqrt{\frac{\log(d(t+1)/\delta)}{t+1}} \vee
  \frac{\log(d(t+1)/\delta)}{t+1}\bigg)} 
\geq 1 - \sum_{t=0}^{\infty}
\frac{\delta}{(t+1)^2}= 1-\frac{\pi^2\delta}{6}.
\end{equation}
